$SATQ$, false, 9, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ$Multiple Choice$SATQ$, $SATQ$Math$SATQ$, $SATQ${"questionId":"e117d3b8","external_id":null,"disclosed_item_id":"08224-DC","source":"disclosed","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"P","domain":"Advanced Math","skill_cd":"P.A.","skill_desc":"Equivalent expressions","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":null,"stem":"<p class=\"stem_paragraph \">If <span class=\"italic\">a</span> and <span class=\"italic\">c</span> are positive numbers, which of the following is equivalent to <span class=\"math_expression \"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/e117d3b8/img_004_24eb8d89.png\" alt=\"the square root of, open parenthesis, a plus c, close parenthesis, cubed, end root, times, the square root of a plus c, end root\"></span></span>?</p>\n","answerOptions":[{"id":"a","content":"<span class=\"math_expression \">\n            <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/e117d3b8/img_000_1f6381b6.png\" alt=\"a plus c\"></span></span>\n"},{"id":"b","content":"<span class=\"math_expression \">\n            <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/e117d3b8/img_001_41d9223c.png\" alt=\"a squared plus c squared\"></span></span>\n"},{"id":"c","content":"<span class=\"math_expression \">\n            <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/e117d3b8/img_002_9a31df4d.png\" alt=\"a squared plus 2 a c plus c squared\"></span></span>\n"},{"id":"d","content":"<span cla